function advancedPhysicsDomain(focus, setup, principle, constraint, trap, check) {
    return { focus, setup, principle, constraint, trap, check };
}

const ADVANCED_PHYSICS_LENSES = [
    {
        name: 'coupled constraint',
        prompt: 'two variables are not independent and the tempting one-line formula gives a plausible but wrong option',
        correct: (domain) => `first impose ${domain.constraint}, then apply ${domain.principle} in the reduced variable set`,
        wrongA: (domain) => `apply ${domain.trap} before checking ${domain.constraint}`,
        wrongB: (domain) => `treat the two coupled variables as independent and fit the answer only by dimensions`,
        wrongC: (domain) => `choose the expression with the fewest symbols, even though it ignores ${domain.check}`
    },
    {
        name: 'limiting-case filter',
        prompt: 'the expression must survive a zero, infinity, symmetry, or equal-parameter limiting test',
        correct: (domain) => `test the result against ${domain.check} after deriving it from ${domain.principle}`,
        wrongA: (domain) => `accept the option that is dimensionally correct but fails ${domain.check}`,
        wrongB: (domain) => `remove the limiting case because it looks singular instead of resolving it physically`,
        wrongC: (domain) => `assume the largest term is always dominant without checking ${domain.constraint}`
    },
    {
        name: 'invariant or conservation shortcut',
        prompt: 'the direct equations are long, but one invariant collapses the algebra',
        correct: (domain) => `identify the invariant implied by ${domain.principle} and use ${domain.constraint} only after choosing the system`,
        wrongA: (domain) => `conserve a quantity that is destroyed by ${domain.trap}`,
        wrongB: (domain) => `write conservation for one particle when the invariant belongs to the full system`,
        wrongC: (domain) => `use endpoint data only and ignore the hidden invariant check ${domain.check}`
    },
    {
        name: 'small-parameter expansion',
        prompt: 'the answer depends on the first non-zero correction, not merely on the leading ideal result',
        correct: (domain) => `expand the exact relation from ${domain.principle} only after enforcing ${domain.constraint}`,
        wrongA: (domain) => `discard the correction that contains ${domain.check}`,
        wrongB: (domain) => `linearize the wrong variable and accidentally keep a higher-order term from ${domain.trap}`,
        wrongC: (domain) => `replace the perturbation by zero at the start and lose the requested effect`
    },
    {
        name: 'vector, sign, and frame audit',
        prompt: 'the numerical magnitude is easy, but direction, sign convention, or frame choice decides the correct option',
        correct: (domain) => `fix the frame and sign convention, resolve the vector part of ${domain.principle}, and then use ${domain.constraint}`,
        wrongA: (domain) => `use scalar magnitudes from ${domain.trap} and attach the direction at the end`,
        wrongB: (domain) => `change frames midway without transforming the relevant velocity, field, or pseudo term`,
        wrongC: (domain) => `reverse the sign because the chosen axis is confused with ${domain.check}`
    }
];

function rotateAdvancedPhysicsOptions(correct, distractors, shift) {
    const base = [correct, ...distractors.slice(0, 3)];
    const values = base.filter((option, index) => base.indexOf(option) === index);
    while (values.length < 4) values.push(`Insufficient advanced-physics conclusion ${values.length}`);
    const offset = shift % 4;
    const o = [...values.slice(offset), ...values.slice(0, offset)];
    return { o, a: o.indexOf(correct) };
}

function buildAdvancedPhysicsQuestionSet(chapterName, domains) {
    if (!Array.isArray(domains) || domains.length !== 10) {
        throw new Error(`Physics chapter ${chapterName} must define exactly 10 advanced domains.`);
    }

    const questions = [];
    const conceptKeys = new Set();

    domains.forEach((domain, domainIndex) => {
        ADVANCED_PHYSICS_LENSES.forEach((lens, lensIndex) => {
            const conceptKey = `${domain.focus} :: ${lens.name}`;
            if (conceptKeys.has(conceptKey)) {
                throw new Error(`Duplicate Physics concept in ${chapterName}: ${conceptKey}`);
            }
            conceptKeys.add(conceptKey);

            const correct = `Use ${domain.focus}: ${lens.correct(domain)}.`;
            const distractors = [
                `Misread ${domain.focus}: ${lens.wrongA(domain)}.`,
                `Over-simplify ${domain.focus}: ${lens.wrongB(domain)}.`,
                `Use a shortcut outside its range: ${lens.wrongC(domain)}.`
            ];
            const { o, a } = rotateAdvancedPhysicsOptions(correct, distractors, domainIndex + lensIndex);
            const number = questions.length + 1;
            questions.push({
                q: `In a problem on ${domain.setup}, the hidden difficulty is ${lens.prompt}. Which option is correct?`,
                o,
                a,
                s: `Unique concept ${number}: ${domain.focus} with ${lens.name}. The governing idea is ${domain.principle}. The necessary constraint is ${domain.constraint}. The common trap is ${domain.trap}. A robust solution must also pass ${domain.check}.`,
                source: `${chapterName} advanced physics concept ${number}`
            });
        });
    });

    if (questions.length !== 50 || conceptKeys.size !== 50) {
        throw new Error(`Physics chapter ${chapterName} generated ${questions.length} questions and ${conceptKeys.size} concepts instead of 50.`);
    }

    return questions;
}

